package com.liskovsoft.smartyoutubetv2.common.oculo;

import android.content.Context;
import android.text.TextUtils;

import com.liskovsoft.sharedutils.helpers.AppInfoHelpers;
import com.liskovsoft.smartyoutubetv2.common.R;

/**
 * Oculo (0.9.0): Oculo's own version numbers (versionName « 0.9.0 », see OCULO.md « Version numbers »). The SmartTube
 * version Oculo is built on is shown only in About: « Oculo 0.9.0 · basé sur SmartTube 32.74 ».
 * {@code R.string.oculo_upstream_version} is generated by smarttubetv/oculo.gradle (resValue); empty upstream, where
 * the title stays « SmartTube 32.74 ».
 */
public final class OculoVersion {
    private OculoVersion() {
    }

    public static String aboutTitle(Context context) {
        String title = String.format("%s %s", context.getString(R.string.app_name), AppInfoHelpers.getAppVersionName(context));
        String upstream = context.getString(R.string.oculo_upstream_version);
        return TextUtils.isEmpty(upstream) ? title : context.getString(R.string.oculo_about_based_on, title, upstream);
    }
}
